  "help.healthScore": "ಪಾವತಿ ಸ್ಟ್ರೀಕ್, ಬಿಲ್‌ಗಳ ಮೇಲಿನ ನಿಯಂತ್ರಣ, ಮುಕ್ತ ಬ್ಯಾಲೆನ್ಸ್ ಮತ್ತು ಸಾಲವನ್ನು ಸಂಯೋಜಿಸುತ್ತದೆ. ಇದು ಮಾರ್ಗದರ್ಶಿಯಾಗಿದೆ, ಕ್ರೆಡಿಟ್ ಸ್ಕೋರ್ ಅಲ್ಲ.",
