  "notifications.lowBuffer.title": "Perovo - ಕಡಿಮೆ ಮೀಸಲು",
  "notifications.lowBuffer.message": "ತುರ್ತು ಬಫರ್ 6 ವಾರಗಳಿಗಿಂತ ಕಡಿಮೆ ಬಿಲ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ - ಹೊಸ ಬದ್ಧತೆಗಳನ್ನು ವಿರಾಮಗೊಳಿಸುವುದನ್ನು ಪರಿಗಣಿಸಿ.",
