  "insight.family-burden": "ಹೌಸ್ಹೋಲ್ಡ್ ಬಿಲ್ಗಳು ಆದಾಯದ ದೊಡ್ಡ ಪಾಲನ್ನು ಬಳಸುತ್ತವೆ - ಹಂಚಿಕೊಂಡ ಬದ್ಧತೆಗಳನ್ನು ಒಟ್ಟಿಗೆ ಪರಿಶೀಲಿಸಿ.",
  "insight.family-dependency": "ಮನೆಯು ಬಿಗಿಯಾದ ಆದಾಯ-ಬಿಲ್‌ಗಳ ಅನುಪಾತವನ್ನು ಅವಲಂಬಿಸಿದೆ - ತುರ್ತು ಯೋಜನೆ ಎಲ್ಲರಿಗೂ ಮುಖ್ಯವಾಗಿದೆ.",
