  "profileHub.scoreWhy.health.what": "ಬಿಲ್ ಹೊರೆ, ಪಾವತಿ ಪದ್ಧತಿ, ಉಳಿತಾಯ ಬಫರ್ ಮತ್ತು ಸಾಲದ ಪ್ರವೃತ್ತಿಯನ್ನು ಸಂಯೋಜಿಸುತ್ತದೆ.",
