  "profileHub.scoreFix.pressure.trimSubscriptions": "ನೀವು ವಿರಾಮಗೊಳಿಸಬಹುದಾದ ಚಂದಾದಾರಿಕೆಗಳು ಮತ್ತು ಐಚ್ಛಿಕ EMIಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
